with open('input.txt','r') as f :
    data = f.read()
    output_data = []
    for i in data.splitlines() :
        string = ''
        if i == ' ':
            continue
        else :
            string = ''
            for j in i.split() :
                if ',' in j :
                    j = j.replace(',','')
                if j.isdecimal() :
                    j = int(j) ** 2
                    string += ' '+str(j)
            output_data.append(string)
    new = []
    for i in output_data :
        new.append(i.strip().split())
with open('output.txt','w') as s :
    for i in new :
        string = ''
        for j in range(len(i)) :
            if j == len(i) - 1 :
                print(f'{i[j]}')
                string += str(i[j])
            else :
                print(f'{i[j]}' , end=',')
                string += str(i[j])+','
        s.write(string+'\n')
